//! The token classifier: how likely a token is a random secret rather than a
//! word, an identifier, a date, a version or a path.
//!
//! A logistic model over character-class, entropy and letter-trigram features. The weights
//! (`model.rs`) and the trigram table (`trigram.bin`) are generated by
//! `tools/classifier/train.py`; see `tools/classifier/README.md`.

mod detect;
mod features;
// Generated by the training script; kept byte-identical to its output.
#[rustfmt::skip]
mod model;

pub(crate) use detect::{is_identifier as is_word_name, ClassifierDetector, ID};

/// int8 log2-probabilities (scaled) of lowercase letter trigrams, 27³ entries.
static TRIGRAM: &[u8; 27 * 27 * 27] = include_bytes!("trigram.bin");

/// `p(secret)` in `[0, 1]`. Empty input scores 0.
pub fn secret_probability(token: &str) -> f32 {
    probability(token) as f32
}

fn probability(token: &str) -> f64 {
    if token.is_empty() {
        return 0.0;
    }
    let f = features::features(token, TRIGRAM);
    let z = model::BIAS
        + f.iter()
            .zip(model::WEIGHTS.iter())
            .map(|(x, w)| x * w)
            .sum::<f64>();
    1.0 / (1.0 + (-z).exp())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_training_script() {
        for &(token, expected) in model::PARITY {
            let p = probability(token);
            assert!(
                (p - expected).abs() < 1e-9 + 1e-6 * expected,
                "{token:?}: rust {p} vs python {expected}"
            );
        }
    }

    #[test]
    fn identifiers_score_low() {
        for t in [
            "getUserAccountSettings",
            "node_modules",
            "2024-11-30",
            "v1.2.3",
        ] {
            let p = secret_probability(t);
            assert!(p < 0.2, "{t}: {p}");
        }
    }

    #[test]
    fn empty_and_tiny() {
        assert_eq!(secret_probability(""), 0.0);
        assert!(secret_probability("a") < 0.5);
    }
}
